output_text:
[
  {
    "id": "no_carts_in_single_file_shelf_aisles",
    "text": "Shopping carts are forbidden inside single-file shelf aisles, i.e. narrow aisles with shelves on both sides.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "singleFileShelfAisle"
        ]
      }
    }
  },
  {
    "id": "no_pushing_cart_into_single_file_aisle",
    "text": "It is forbidden to push a cart into a single-file shelf aisle.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        }
      },
      "events": {
        "cartEntersSingleFileShelfAisle": {
          "pre": {
            "and": [
              "hasCart",
              "MOVE"
            ]
          },
          "post": "singleFileShelfAisle"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "cartEntersSingleFileShelfAisle"
    }
  },
  {
    "id": "set_down_cart_only_at_single_file_mouth",
    "text": "A shopper may set down the cart only at the mouth of a single-file shelf aisle.",
    "abstraction": {
      "state_properties": {
        "singleFileMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        }
      },
      "events": {
        "setDownCart": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "setDownCart",
          {
            "not": "singleFileMouth"
          }
        ]
      }
    }
  },
  {
    "id": "retrieve_cart_after_parking_at_aisle_mouth",
    "text": "After parking a cart at the mouth of a single-file shelf aisle, the shopper is obliged to retrieve it before leaving.",
    "abstraction": {
      "state_properties": {
        "singleFileMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        }
      },
      "events": {
        "parkCartAtSingleFileMouth": {
          "pre": {
            "and": [
              "singleFileMouth",
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        },
        "retrieveCartAtSingleFileMouth": {
          "pre": {
            "and": [
              "singleFileMouth",
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "parkCartAtSingleFileMouth",
      "discharge": "retrieveCartAtSingleFileMouth"
    }
  },
  {
    "id": "return_to_cart_after_single_file_item",
    "text": "After taking an item from within a single-file shelf aisle, the shopper must return to the aisle mouth and pick the cart back up.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        },
        "singleFileMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        }
      },
      "events": {
        "singleFileShelfInteraction": {
          "pre": {
            "and": [
              "singleFileShelfAisle",
              "INTERACT"
            ]
          },
          "post": null
        },
        "retrieveCartAtSingleFileMouth": {
          "pre": {
            "and": [
              "singleFileMouth",
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "singleFileShelfInteraction",
      "discharge": "retrieveCartAtSingleFileMouth"
    }
  },
  {
    "id": "no_cartless_roaming_outside_excursion_zone",
    "text": "Walking without a cart is forbidden except in the entrance cart-pickup area and during a single-file-aisle cart-free excursion.",
    "abstraction": {
      "state_properties": {
        "entryCartPickupArea": {
          "or": [
            "at(0,7)",
            "at(1,7)"
          ]
        },
        "singleFileShelfAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        },
        "singleFileMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        },
        "cartFreeExcursionZone": {
          "or": [
            "singleFileShelfAisle",
            "singleFileMouth"
          ]
        },
        "cartFreeAllowedZone": {
          "or": [
            "entryCartPickupArea",
            "cartFreeExcursionZone"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "MOVE",
          {
            "not": "hasCart"
          },
          {
            "not": "cartFreeAllowedZone"
          }
        ]
      }
    }
  },
  {
    "id": "do_not_abandon_cart_at_cart_compatible_shelf",
    "text": "At cart-compatible shelf fronts, shoppers should keep the cart rather than setting it down.",
    "abstraction": {
      "state_properties": {
        "singleFileMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        },
        "cartCompatibleShelfFront": {
          "and": [
            "adjShelf",
            {
              "gt": [
                "freeWidthH",
                1
              ]
            },
            {
              "not": "singleFileMouth"
            }
          ]
        }
      },
      "events": {
        "setDownCartAtCartCompatibleShelf": {
          "pre": {
            "and": [
              "cartCompatibleShelfFront",
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "setDownCartAtCartCompatibleShelf"
    }
  },
  {
    "id": "no_cartless_interaction_at_cart_compatible_shelves",
    "text": "Shelf interactions without a cart are forbidden unless the shelf is inside a single-file aisle where carts are not allowed.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        },
        "cartCompatibleShelfFront": {
          "and": [
            "adjShelf",
            {
              "not": "singleFileShelfAisle"
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "cartCompatibleShelfFront",
          "INTERACT",
          {
            "not": "hasCart"
          }
        ]
      }
    }
  }
]
